<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Edit Peminjaman</title></head><body><h1>Edit Peminjaman</h1><?php if($errors->any()): ?><ul><?php $__currentLoopData = $errors->all(); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $error): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><?php echo e($error); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ul><?php endif; ?><form method="POST" action="<?php echo e(route('peminjaman.update',$data['id'])); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><input name="kode_peminjaman" value="<?php echo e(old('kode_peminjaman',$data['kode_peminjaman'])); ?>"><input name="nama_peminjam" value="<?php echo e(old('nama_peminjam',$data['nama_peminjam'])); ?>"><input name="nomor_identitas" value="<?php echo e(old('nomor_identitas',$data['nomor_identitas'])); ?>"><input type="number" name="jumlah_alat" min="1" max="10" value="<?php echo e(old('jumlah_alat',$data['jumlah_alat'])); ?>"><select name="alat_id"><?php $__currentLoopData = $alat; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($item['id']); ?>" <?php if($item['id']==$data['alat_id']): echo 'selected'; endif; ?>><?php echo e($item['nama_alat']); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button>Simpan</button></form><a href="<?php echo e(route('peminjaman.index')); ?>">Kembali</a></body></html><?php /**PATH D:\Praktikum Pemrogram Web\praktikum_web_2401020151\TipeB_Sistem_Peminjaman_Alat\resources\views/peminjaman-edit.blade.php ENDPATH**/ ?>